#(  .DATA_WIDTH (DATA_WIDTH),
    .ADDR_WIDTH (ADDR_WIDTH),
    .DEPTH      (DEPTH))
U_RMSNORM_QUANT_2_fifo_w256_d3_S_ShiftReg (
    .clk        (clk),
    .we         (push),
    .addr       (addr),
    .din        (if_din),
    .dout       (if_dout)
);
//------------------------Task and function--------------

//------------------------Body---------------------------
// has num_data_valid ? 
assign if_num_data_valid = mOutPtr + 1'b1; // yes
assign if_fifo_cap = DEPTH; // yes 

// has almost full ? 
assign if_full_n  = full_n; //no 
assign if_empty_n = empty_n;

assign push = (if_write & if_write_ce) & full_n;
assign pop  = (if_read & if_read_ce) & empty_n;
assign addr = mOutPtr[ADDR_WIDTH] == 1'b0 ? mOutPtr[ADDR_WIDTH-1:0]:{ADDR_WIDTH{1'b0}};

// full_n
always @(posedge clk ) begin
    if (reset == 1'b1)
        full_n <= 1'b1;
    else if (push & ~pop) begin
        if (mOutPtr == DEPTH - 2)
            full_n <= 1'b0;
    end
    else if (~push & pop)
        full_n <= 1'b1;
end

// almost_full_n 

// empty_n
always @(posedge clk ) begin
    if (reset == 1'b1)
        empty_n <= 1'b0;
    else if (push & ~pop)
        empty_n <= 1'b1;
    else if (~push & pop) begin
        if (mOutPtr == 0)
